import { CredentialStatus } from "@accessbuddy/shared";

/**
 * What confirming programming does to a credential's status and expiry.
 *
 * Confirming clears the programmingRequired flag. The only status change is
 * reactivating an `expired` credential whose staged expiry is in the future
 * (the programmer has confirmed the access system holds the new expiry). Every
 * other status, notably `returned` and `deactivated`, is left exactly as it
 * is: a fob flagged for removal after an exchange must stay `returned` once
 * the programmer confirms it is off the access system.
 */
export function resolveConfirmProgramming(
  cred: { status: string; pendingExpiresAt: Date | null },
  now: Date
): { promotedExpiresAt: Date | null; shouldReactivate: boolean } {
  const promotedExpiresAt = cred.pendingExpiresAt;
  const shouldReactivate =
    cred.status === CredentialStatus.EXPIRED &&
    !!promotedExpiresAt &&
    promotedExpiresAt > now;
  return { promotedExpiresAt, shouldReactivate };
}
