import { sql } from "drizzle-orm";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import { createMigrationClient } from "./client";
import { collectExpectedTables, findMissingTables, type ExpectedTable } from "./verify-migrations";

const MIGRATIONS_FOLDER = "./drizzle";

async function runMigrations() {
  console.log("Running migrations...");
  const { db, close } = createMigrationClient();
  let expected: ExpectedTable[] = [];
  let missing: ExpectedTable[] = [];
  try {
    await migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });

    // Post-migration integrity check. Drizzle trusts its own bookkeeping
    // (drizzle.__drizzle_migrations): a journal entry marked applied is
    // silently skipped even if its objects were never created. That exact
    // failure took down OTP login in prod (0010-0012 marked applied,
    // rate_limit_buckets missing). Verify the journal's promises against
    // the live database and refuse to hand over a broken schema.
    expected = collectExpectedTables(MIGRATIONS_FOLDER);
    const rows = (await db.execute(
      sql`SELECT table_name FROM information_schema.tables WHERE table_schema = 'public'`
    )) as unknown as Array<{ table_name: string }>;
    const existing = new Set(rows.map((r) => r.table_name));
    missing = findMissingTables(expected, existing);
  } finally {
    await close();
  }

